import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	
	    static final long MOD=998244353;
	    static final int MAXN=200005;
	    static long[] inv=new long[MAXN];
	    static long[] H=new long[MAXN];
	    static void pc(){
	        inv[1]=1;
	        for(int i=2;i<MAXN;i++){
	            inv[i]=(MOD-(MOD/i)*inv[(int)(MOD%i)]%MOD)%MOD;
	        }
	        H[0]=0;
	        for(int i=1;i<MAXN;i++){
	            H[i]=(H[i-1]+inv[i])%MOD;
	        }
	    }
	    public static void main(String[] args){
	        Scanner sc=new Scanner(System.in);
	        pc();
	        int t=sc.nextInt();
	        while(t-->0){
	            int n=sc.nextInt();
	            long ans=0;
	            for(int k=1;k<=n;k++){
	                long val=sc.nextLong();
	                long coe=(H[k-1]+H[n-k])%MOD;
	                ans=(ans+(val%MOD)*coe)%MOD;
	            }
	            System.out.println(ans);
	        }
	    }
	    
	    
	    
		// your code goes here

	}
